#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using pii = pair<int, int>;

constexpr int D4X[4] = {0, 0, -1, 1};
constexpr int D4Y[4] = {-1, 1, 0, 0};

struct Edge {
    int src, dst;
    ll capacity, current_flow;
    Edge(int s, int d, ll c) : src(s), dst(d), capacity(c), current_flow(0) {}
};

class MaxFlowAlgorithm {
public:
    const ll INF = 1e18;
    vector<Edge> edgelist;
    vector<vector<int>> adj;
    int V, source, sink;
    vector<int> depth, it;
    queue<int> q;

    MaxFlowAlgorithm(int nodes, int s, int t)
        : V(nodes), source(s), sink(t) {
        adj.resize(V);
        depth.resize(V);
        it.resize(V);
    }

    void insert(int u, int v, ll cap) {
        edgelist.emplace_back(u, v, cap);
        edgelist.emplace_back(v, u, 0);
        adj[u].push_back(edgelist.size() - 2);
        adj[v].push_back(edgelist.size() - 1);
    }

    bool build_levels() {
        fill(depth.begin(), depth.end(), -1);
        depth[source] = 0;
        q.push(source);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int idx : adj[u]) {
                auto& e = edgelist[idx];
                if (e.capacity - e.current_flow > 0 && depth[e.dst] == -1) {
                    depth[e.dst] = depth[u] + 1;
                    q.push(e.dst);
                }
            }
        }
        return depth[sink] != -1;
    }

    ll augment(int u, ll bottleneck) {
        if (u == sink) return bottleneck;
        for (int& i = it[u]; i < (int)adj[u].size(); ++i) {
            int idx = adj[u][i];
            auto& e = edgelist[idx];
            if (depth[e.dst] == depth[u] + 1 && e.capacity - e.current_flow > 0) {
                ll flow = augment(e.dst, min(bottleneck, e.capacity - e.current_flow));
                if (flow > 0) {
                    e.current_flow += flow;
                    edgelist[idx ^ 1].current_flow -= flow;
                    return flow;
                }
            }
        }
        return 0;
    }

    ll max_flow() {
        ll total = 0;
        while (build_levels()) {
            fill(it.begin(), it.end(), 0);
            while (ll flow = augment(source, INF)) {
                total += flow;
            }
        }
        return total;
    }
};

int grid_size, time_limit;
string resource_grid[15];
string capacity_grid[15];
int bfs_dist[15][15];

inline bool inside(int r, int c) {
    return r >= 0 && r < grid_size && c >= 0 && c < grid_size && resource_grid[r][c] != 'Y' && resource_grid[r][c] != 'Z';
}

void multi_source_bfs(int sr, int sc) {
    memset(bfs_dist, -1, sizeof(bfs_dist));
    queue<pair<int, int>> q;
    q.emplace(sr, sc);
    bfs_dist[sr][sc] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + D4X[k], ny = y + D4Y[k];
            if (inside(nx, ny) && bfs_dist[nx][ny] == -1) {
                bfs_dist[nx][ny] = bfs_dist[x][y] + 1;
                q.emplace(nx, ny);
            }
        }
    }
    for (int i = 0; i < grid_size; ++i)
        for (int j = 0; j < grid_size; ++j)
            if (bfs_dist[i][j] == -1) bfs_dist[i][j] = 1e9;
}

int dp_cache[65][12][12][12][12];
bool computed[65][12][12][12][12];

bool connectivity_check(int time_step, int r1, int c1, int r2, int c2) {
    if (bfs_dist[r1][c1] < time_step) return false;
    if (r1 == r2 && c1 == c2) return true;
    if (time_step >= time_limit) return false;
    if (bfs_dist[r1][c1] <= time_step) return false;
    if (computed[time_step][r1][c1][r2][c2]) return dp_cache[time_step][r1][c1][r2][c2];
    computed[time_step][r1][c1][r2][c2] = true;
    for (int k = 0; k < 4; ++k) {
        int nr = r1 + D4X[k], nc = c1 + D4Y[k];
        if (nr < 0 || nr >= grid_size || nc < 0 || nc >= grid_size) continue;
        if (resource_grid[nr][nc] == 'Y' || resource_grid[nr][nc] == 'Z') continue;
        if (connectivity_check(time_step + 1, nr, nc, r2, c2)) {
            dp_cache[time_step][r1][c1][r2][c2] = true;
            return true;
        }
    }
    dp_cache[time_step][r1][c1][r2][c2] = false;
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    memset(dp_cache, -1, sizeof(dp_cache));
    cin >> grid_size >> time_limit;
    for (int i = 0; i < grid_size; ++i) cin >> resource_grid[i];
    for (int i = 0; i < grid_size; ++i) cin >> capacity_grid[i];

    for (int i = 0; i < grid_size; ++i)
        for (int j = 0; j < grid_size; ++j)
            if (resource_grid[i][j] == 'Z') {
                multi_source_bfs(i, j);
                goto found_z;
            }
    found_z:

    vector<pair<int, int>> res_list, cap_list;
    for (int i = 0; i < grid_size; ++i)
        for (int j = 0; j < grid_size; ++j)
            if (resource_grid[i][j] != 'Z' && resource_grid[i][j] != 'Y' && resource_grid[i][j] != '0')
                res_list.emplace_back(i, j);
    for (int i = 0; i < grid_size; ++i)
        for (int j = 0; j < grid_size; ++j)
            if (capacity_grid[i][j] != 'Z' && capacity_grid[i][j] != 'Y' && capacity_grid[i][j] != '0')
                cap_list.emplace_back(i, j);

    int num_nodes = res_list.size() + cap_list.size() + 2;
    MaxFlowAlgorithm mfa(num_nodes, 0, num_nodes - 1);

    for (int i = 0; i < res_list.size(); ++i) {
        ll capacity = resource_grid[res_list[i].first][res_list[i].second] - '0';
        mfa.insert(0, i + 1, capacity);
    }
    for (int i = 0; i < cap_list.size(); ++i) {
        ll capacity = capacity_grid[cap_list[i].first][cap_list[i].second] - '0';
        mfa.insert(res_list.size() + 1 + i, num_nodes - 1, capacity);
    }

    for (int i = 0; i < res_list.size(); ++i)
        for (int j = 0; j < cap_list.size(); ++j)
            if (connectivity_check(0, res_list[i].first, res_list[i].second, cap_list[j].first, cap_list[j].second))
                mfa.insert(i + 1, res_list.size() + 1 + j, 10000000LL);

    cout << mfa.max_flow() << '\n';
    return 0;
}
